100→  get("ledger/account?number=1920,2050,2400,2600,7770,8050&fields=*"),
101→  get(`ledger/accountingPeriod?startFrom=${months[0]}-01&startTo=${months[months.length - 1]}-02&count=12&fields=*`),
102→]);
103→
104→const invoices = invoicesRes.values || [];
105→const payTypes = payTypesRes.values || [];
106→const suppliers = suppliersRes.values || [];
107→const suppInvoices = suppInvRes.values || [];
108→const accounts = accountsRes.values || [];
109→
110→const acctMap: Record<number, number> = {};
111→for (const a of accounts) acctMap[a.number] = a.id;
112→
113→// Period map: "YYYY-MM" → period object (from single wide query)
114→const periodMap: Record<string, any> = {};
115→for (const p of (periodsRes.values || [])) {
116→  const m = (p.start || "").substring(0, 7);
117→  if (months.includes(m)) periodMap[m] = p;
118→}
119→
120→console.log(`Accounts: ${Object.entries(acctMap).map(([n,id]) => `${n}=${id}`).join(", ")}`);
121→console.log(`Periods: ${Object.entries(periodMap).map(([m,p]) => `${m} → id=${p.id} (${p.start} to ${p.end})`).join(", ")}`);
122→console.log(`Invoices found: ${invoices.length} | Supplier invoices: ${suppInvoices.length} | Suppliers: ${suppliers.length}`);
123→console.log(`Payment types: ${payTypes.map((pt: any) => `${pt.description}(debit=${pt.debitAccount?.number})`).join(", ")}`);
124→
125→// Log invoices with outstanding amounts (these are candidates for matching)
126→const outstandingInvs = invoices.filter((inv: any) => (inv.amountCurrencyOutstanding ?? inv.amountOutstanding ?? 0) > 0.01);
127→console.log(`Outstanding invoices: ${outstandingInvs.length}`);
128→for (const inv of outstandingInvs) {
129→  console.log(`  Inv #${inv.invoiceNumber} | ${inv.customer?.name} | outstanding=${inv.amountCurrencyOutstanding ?? inv.amountOutstanding} | total=${inv.amount}`);
130→}
131→
132→// ── STEP 0: Opening balance voucher ──
133→
134→console.log(`\n=== STEP 0: Opening balance voucher ===`);
135→
136→let obVoucherId: number | null = null;
137→if (openingBalance !== 0) {
138→  const obRes = await post("ledger/voucher", {
139→    date: firstCsvDate, description: "Inngående balanse",
140→    postings: [
141→      { row: 1, date: firstCsvDate, description: "Inngående balanse", account: { id: acctMap[1920] },
142→        amount: openingBalance, amountCurrency: openingBalance, amountGross: openingBalance, amountGrossCurrency: openingBalance, currency: { id: 1 } },
143→      { row: 2, date: firstCsvDate, description: "Inngående balanse", account: { id: acctMap[2050] },
144→        amount: -openingBalance, amountCurrency: -openingBalance, amountGross: -openingBalance, amountGrossCurrency: -openingBalance, currency: { id: 1 } },
145→    ],
146→  });
147→  obVoucherId = obRes?.value?.id;
148→  console.log(`OB voucher created: id=${obVoucherId || "ERROR"}`);
149→
150→  // Verify OB voucher
151→  if (obVoucherId) {
152→    const obVerify = await get(`ledger/voucher/${obVoucherId}?fields=*,postings(*)`);
153→    const obPostings = obVerify?.value?.postings || [];
154→    console.log(`  Verified: ${obPostings.length} postings, date=${obVerify?.value?.date}`);
155→    for (const p of obPostings) {
156→      console.log(`    row=${p.row} acct=${p.account?.number || p.account?.id} amount=${p.amount}`);
157→    }
158→  }
159→} else {
160→  console.log(`Opening balance is 0 — no OB voucher needed`);
161→}
162→
163→// ── STEP 2: Payment type ──
164→
165→const payType = payTypes.find((pt: any) => pt.debitAccount?.number === 1920);
166→if (!payType) { console.error("No payment type with debitAccount 1920"); process.exit(1); }
167→console.log(`\nPayment type: id=${payType.id} "${payType.description}" debit=${payType.debitAccount?.number}`);
168→
169→// ── STEP 3: Customer payments (parallel) ──
170→
171→console.log(`\n=== STEP 3: Customer payments ===`);
172→
173→const outstandingTracker: Record<number, number> = {};
174→for (const inv of invoices) outstandingTracker[inv.id] = inv.amountCurrencyOutstanding ?? inv.amountOutstanding ?? 0;
175→
176→// Build payment plan first (sequential matching to avoid double-booking), then fire all at once
177→const paymentPlan: { invId: number; invNum: number; amount: number; date: string; custName: string }[] = [];
178→for (const line of customerLines) {
179→  const match = line.desc.match(/Innbetaling fra (.+?) \/ Faktura/);
180→  const custName = match ? match[1].trim() : "";
181→  const amount = line.inn;
182→
183→  const candidates = invoices.filter((inv: any) =>
184→    (inv.customer?.name || "").toLowerCase().includes(custName.toLowerCase()) && outstandingTracker[inv.id] > 0.01
185→  );
186→
187→  let best = candidates.find((inv: any) => Math.abs(outstandingTracker[inv.id] - amount) < 0.01);
188→  if (!best) {
189→    const larger = candidates.filter((inv: any) => outstandingTracker[inv.id] >= amount - 0.01);
190→    larger.sort((a: any, b: any) => outstandingTracker[a.id] - outstandingTracker[b.id]);
191→    best = larger[0] || candidates.sort((a: any, b: any) => a.invoiceNumber - b.invoiceNumber)[0];
192→  }
193→
194→  if (best) {
195→    const paidAmount = Math.min(amount, outstandingTracker[best.id]);
196→    outstandingTracker[best.id] -= paidAmount;
197→    paymentPlan.push({ invId: best.id, invNum: best.invoiceNumber, amount: paidAmount, date: line.date, custName });
198→    console.log(`  Plan: inv #${best.invoiceNumber} ← ${paidAmount} from "${custName}" on ${line.date}`);
199→  } else {
200→    console.log(`  WARNING: No invoice match for "${custName}" amount=${amount}`);
201→  }
202→}
203→
204→const payResults = await Promise.all(
205→  paymentPlan.map(p => put(`invoice/${p.invId}/:payment?paymentDate=${p.date}&paymentTypeId=${payType.id}&paidAmount=${p.amount}`, {}))
206→);
207→payResults.forEach((pr, i) => {
208→  const p = paymentPlan[i];
209→  console.log(`  Pay inv #${p.invNum}: ${p.amount} for "${p.custName}" → ${pr?.value ? "OK" : "FAIL"}`);
210→});
211→
212→// Verify: GET each paid invoice to confirm outstanding went to 0
213→console.log(`\n  --- Verifying invoice payments ---`);
214→const payVerifyResults = await Promise.all(
215→  paymentPlan.map(p => get(`invoice/${p.invId}?fields=id,invoiceNumber,amount,amountOutstanding,amountCurrencyOutstanding`))
216→);
217→for (let i = 0; i < paymentPlan.length; i++) {
218→  const p = paymentPlan[i];
219→  const inv = payVerifyResults[i]?.value;
220→  if (inv) {
221→    const outstanding = inv.amountCurrencyOutstanding ?? inv.amountOutstanding ?? "?";
222→    console.log(`  Inv #${inv.invoiceNumber}: total=${inv.amount} outstanding=${outstanding} ${outstanding === 0 || outstanding === 0.0 ? "✓ PAID" : "⚠ STILL OUTSTANDING"}`);
223→  }
224→}
225→
226→// ── STEPS 4+5: Combined voucher (suppliers + non-invoice) ──
227→
228→console.log(`\n=== STEPS 4+5: Combined voucher ===`);
229→
230→const supplierMap: Record<string, number> = {};
231→for (const s of suppliers) supplierMap[s.name.toLowerCase()] = s.id;
232→
233→const voucherPostings: any[] = [];
234→let row = 1;
235→
236→for (const line of supplierLines) {
237→  const supplierName = line.desc.replace(/Betaling\s+(Proveedor|Supplier|Leverandor|Lieferant|Fournisseur|Fornecedor)\s+/i, "").trim();
238→  const amount = Math.abs(line.ut);
239→  const suppId = Object.entries(supplierMap).find(([name]) => name.includes(supplierName.toLowerCase()))?.[1];
240→
241→  console.log(`  Supplier: "${supplierName}" amount=${amount} supplierId=${suppId || "NOT FOUND"}`);
242→
243→  voucherPostings.push({
244→    row: row++, date: line.date, description: `Betaling ${supplierName}`, account: { id: acctMap[2400] },
245→    amount, amountCurrency: amount, amountGross: amount, amountGrossCurrency: amount,
246→    ...(suppId ? { supplier: { id: suppId } } : {}), currency: { id: 1 },
247→  });
248→  voucherPostings.push({
249→    row: row++, date: line.date, description: `Betaling ${supplierName}`, account: { id: acctMap[1920] },
250→    amount: -amount, amountCurrency: -amount, amountGross: -amount, amountGrossCurrency: -amount, currency: { id: 1 },
251→  });
252→}
253→
254→const contraAcctMap: Record<string, number> = {
255→  Bankgebyr: acctMap[7770], Renteinntekter: acctMap[8050], Skattetrekk: acctMap[2600],
256→};
257→
258→for (const line of nonInvoiceLines) {
259→  const isIncoming = line.inn > 0;
260→  const absAmount = isIncoming ? line.inn : Math.abs(line.ut);
261→  const keyword = Object.keys(contraAcctMap).find(k => line.desc.includes(k)) || "Bankgebyr";
262→  const contraId = contraAcctMap[keyword] || acctMap[7770];
263→
264→  console.log(`  Non-invoice: "${line.desc}" amount=${isIncoming ? "+" : "-"}${absAmount} contra=${keyword}`);
265→
266→  if (isIncoming) {
267→    voucherPostings.push({ row: row++, date: line.date, description: line.desc, account: { id: acctMap[1920] },
268→      amount: absAmount, amountCurrency: absAmount, amountGross: absAmount, amountGrossCurrency: absAmount, currency: { id: 1 } });
269→    voucherPostings.push({ row: row++, date: line.date, description: line.desc, account: { id: contraId },
270→      amount: -absAmount, amountCurrency: -absAmount, amountGross: -absAmount, amountGrossCurrency: -absAmount, currency: { id: 1 } });
271→  } else {
272→    voucherPostings.push({ row: row++, date: line.date, description: line.desc, account: { id: contraId },
273→      amount: absAmount, amountCurrency: absAmount, amountGross: absAmount, amountGrossCurrency: absAmount, currency: { id: 1 } });
274→    voucherPostings.push({ row: row++, date: line.date, description: line.desc, account: { id: acctMap[1920] },
275→      amount: -absAmount, amountCurrency: -absAmount, amountGross: -absAmount, amountGrossCurrency: -absAmount, currency: { id: 1 } });
276→  }
277→}
278→
279→let combinedVoucherId: number | null = null;
280→if (voucherPostings.length > 0) {
281→  const earliestDate = [...supplierLines, ...nonInvoiceLines].sort((a, b) => a.date.localeCompare(b.date))[0]?.date || firstCsvDate;
282→  const vRes = await post("ledger/voucher", { date: earliestDate, description: "Bank reconciliation - payments", postings: voucherPostings });
283→  combinedVoucherId = vRes?.value?.id;
284→  console.log(`Combined voucher: id=${combinedVoucherId || "ERROR"} (${voucherPostings.length} postings)`);
285→
286→  // Verify combined voucher
287→  if (combinedVoucherId) {
288→    const cvVerify = await get(`ledger/voucher/${combinedVoucherId}?fields=*,postings(*)`);
289→    const cvPostings = cvVerify?.value?.postings || [];
290→    console.log(`  Verified: ${cvPostings.length} postings on voucher ${combinedVoucherId}`);
291→    for (const p of cvPostings) {
292→      console.log(`    row=${p.row} acct=${p.account?.number || p.account?.id} amount=${p.amount} desc="${p.description}"`);
293→    }
294→  }
295→}
296→
297→// ── STEP 6: Bank statement import ──
298→
299→console.log(`\n=== STEP 6: Bank statement import ===`);
300→
301→function toSbankenCsv(lines: CsvLine[]): string {
302→  const fmt = (n: number) => n.toFixed(2).replace(".", ",");
303→  const fmtDate = (d: string) => d.split("-").reverse().join(".");
304→  const openSaldo = lines[0].saldo - lines[0].inn + Math.abs(lines[0].ut || 0);
305→  const closeSaldo = lines[lines.length - 1].saldo;
306→  let out = `"Inngående saldo ${fmtDate(lines[0].date)}";"${fmt(openSaldo)}"\n`;
307→  out += `"Utgående saldo ${fmtDate(lines[lines.length - 1].date)}";"${fmt(closeSaldo)}"\n`;
308→  out += `"Bokført";"Rentedato";"Beskrivelse";"Beløp"\n`;
309→  for (const l of lines) {
310→    const d = fmtDate(l.date);
311→    const amount = l.inn > 0 ? l.inn : l.ut; // Ut already negative
312→    out += `"${d}";"${d}";"${l.desc}";"${fmt(amount)}"\n`;
313→  }
314→  return out;
315→}
316→
317→const sbankenCsv = toSbankenCsv(csvLines);
318→console.log(`Sbanken CSV (${sbankenCsv.split("\n").length - 1} lines):`);
319→for (const line of sbankenCsv.split("\n").filter(l => l.trim())) {
320→  console.log(`  ${line}`);
321→}
322→
323→const formData = new FormData();
324→formData.append("file", new Blob([sbankenCsv], { type: "text/csv" }), "bankstatement.csv");
325→const importRes = await post(
326→  `bank/statement/import?bankId=112&accountId=${acctMap[1920]}&fromDate=${firstCsvDate}&toDate=${dayAfterLast}&fileFormat=SBANKEN_BEDRIFT_CSV`,
327→  formData, true
328→);
